var classes := {"稀有": "rare", "精英": "rare", "前所未见": "very_rare", "亘古未有": "very_rare", "首领": "very_rare", "守层者": "guardian", "被封印者": "abyss", "未知存在": "abyss", "古神": "abyss"}
var seed := str(logic._rule().snapshot().get("seed", "0000000000000000"))
var rng := XRandomStream.create(XRandomStream.derive(seed, "rift_alien|%d" % int(logic.troop_id)), "rift_alien")
var tag := RegEx.create_from_string("^【([^】]+)】")
for i in logic.enemies.size():
	var e = logic.enemies[i]
	var m := tag.search(str(e.data().get("name", "")))
	if m == null:
		continue
	var cls := str(classes.get(m.get_string(1), ""))
	if cls == "":
		continue
	var look := {"pulse": cls == "guardian", "flash": false, "tier": ""}
	if cls == "rare" or cls == "very_rare":
		look.flash = rng.next_float("rift_alien.flash", "%d:%d" % [i, int(e.enemy_id)]) * 100.0 < 11.0
	e.set_meta("xrift_look", look)

